            return True
        except Exception as e:
            # logger.error(f'check clound server error: {e}')
            # self.clound_server = False
            pass

        return False

    def _check_local_server(self) :
        try:
            if self.client is None or self.zmq_prompt is None:
                return False

            data = {
                    "api" : "/api/state",
                    "data" : json.dumps({})
                }
            self.client.send_question(data)
            time.sleep(1)

            if self.client.get_zmq_state() == ZMQState.uninit:
                return False

            if self.client.get_zmq_state() == ZMQState.init:
                data = {
                    "api" : "/api/prefill",
                    "data" : json.dumps(self.zmq_prompt.get_sys_msg(),ensure_ascii=False)
                }
                self.client.send_question(data)
                return False

            if self.client.get_zmq_state() == ZMQState.prefill:
                return False

            return True
        except Exception as e:
            logger.error(f'check local server error: {e}')

        return False

    def _check_cloud_tts(self) :
        try:
            import websocket
            ws = websocket.create_connection(
                                ALI_TTS_URL,
                                timeout=5,
                                sslopt={
                                    # "cert_reqs": ssl.CERT_REQUIRED,   # 或 ssl.CERT_NONE
                                    "check_hostname": True
                                },
                            )
            ws.close()
            return True
        except websocket._exceptions.WebSocketBadStatusException as e:
            if e.status_code in (401, 403):
                # ✅ 鉴权失败 ≠ 网络失败
                return True
        except Exception as e:
            pass

        return False

    def _check_speak_state(self) :
        t1 = time.perf_counter()
        SILENCE_TIME = 60*1
        if t1 - self.robot.last_speak_time_ > SILENCE_TIME:
            return True
        return False


    def on_zmq_state(self, state) :
        self.zmq_state = ZMQState(int(state))
        # logger.debug(f"[INFO] on_zmq_state: {self.zmq_state}")

    def run(self) :
        logger.debug ('start pub state thread')



        while self.is_running :
            try:
                self.clound_server = self._check_clound_server()
                self.local_server = self._check_local_server()
                self.cloud_tts = self._check_cloud_tts()
                self.speak_state = self._check_speak_state()


                self.gpt_state  = True
                if self.clound_server is False and self.local_server is False :
                    self.gpt_state = False

                llm_name = 'no'
                if self.clound_server is True :
                    llm_name = 'clound'
                elif self.local_server is True :
                    llm_name = 'local'

                # logger.debug(f'llm_name: {llm_name}')
                pub_gpt_state(self.gpt_state, llm_name, self.speak_state)


            except Exception as e :
                logger.error(f'app thread error: {e}')

            time.sleep(2)

import subprocess
from log import logger
import re

def shell_set_volume(raw_val) :
    # raw_val = str(req.get('value', '')).strip()
            # 只允许 0-100 （可带 % 或不带）
    # m = re.fullmatch(r'(\d{1,3})%', raw_val)
    m = re.search(r'([0-9]+)\s*%', raw_val)
    if m is None :
        return 'format error'

    val = int(m.group(1))
    if val < 0 or val > 100:
        return 'value must be between 0 and 100'

    cmd_val = ''
    if '%+' in raw_val:
        cmd_val = f"{val}%+"
    elif '%-' in raw_val:
        cmd_val = f"{val}%-"
    else:
        cmd_val = f"{val}%"

    cmd = f"amixer set Speaker {cmd_val}"
    perform_cmd(cmd)

def perform_cmd(cmd) :
    try :
        # 执行 'ls -l' 命令
        result = subprocess.run(cmd, shell=True, stdout=subprocess.PIPE)

        # 输出结果
        logger.info(f'cmd: {cmd}, Returned code: {result.returncode}')
    except Exception as e :
        logger.error(f'perform shell error: {e}')

