class G1PubPrompt:
    def __init__(self, robot: Robot):
        self.robot = robot

    def _change2mnn(self, messages):
        new_messages = []

        for message in messages:
            role = message['role']
            content = message['content']
            content_str = ''
            if isinstance(content, list):
                for item in content:
                    if item['type'] == 'text':
                        content_str += item['text']
                    elif item['type'] == 'image_url':
                        content_str += item['image_url']
            else:
                content_str = content

            new_messages.append({
                'role' : role,
                'content' : content_str
            })

        return new_messages

    def _get_sys_msg(self) :
        role_str = self.robot.config_manager_.basic_config_['name']
        sys_prompt = f"""
        {role_str}
        {basic_skill}
        """

        nav_points = self.robot.config_manager_.exhibition_config_
        if len(nav_points) > 0 :
            sys_prompt += f"""
            {nav_skill}

            ## 导航列表
            {nav_points}
            """
        else :
            sys_prompt += move_skill

        sys_prompt += tips
        sys_prompt += """
        ## 意图识别\n 
        * 你的声音来自于机器人麦克风，难以避免噪声输入，不是意图与你说话的人声输入；\n
        * 噪声, 非常确定不是意图与机器人（你）对话，你只回答： <|intention_no|> ; \n 
        * 只要是请求类、指令类、咨询类、打招呼类问题都要属于意图与你讲话，切记！！！;
        """

        user_knowledge = self.robot.config_manager_.knowledge_config_
