    def _create_file_name(self) :
        sn = <GO2设备_01>()

        return f'{sn}_{str(uuid4())}'

    def upload_picture(self, jpeg, payload_data) :
        v_w = None

        try:
            file_like_object = BytesIO(jpeg)
            response = self.session_.post(
                            url = BASE_URL + URI_UPLOAD_FILE,
                            files={
                                'file': (f'{self._create_file_name()}.jpg', file_like_object, 'image/jpeg')
                                },
                            data = {
                                'data' : payload_data
                            },
                            # verify=False
                        )

            if response.status_code != 200:
                logger.error(response)
                return None

            data = response.json()
            print (f'response : {data}')

            if 'v_w' in data :
                v_w = data['v_w']
        except Exception as e :
            logger.error(e)

        return v_w


